// Get inputs passed into this sub-workflow
const triggerInput = $('When Executed by Another Workflow').first().json;
const memberId = triggerInput.member_id ?? null;
const serviceCode = triggerInput.service_code ?? null;

// Parsed claims.json from the previous node
const claims = $input.first().json.data;

// Validate input
if (!memberId || !serviceCode) {
  return [
    {
      json: {
        tool: 'CLAIMS',
        status: 'INVALID_INPUT',
        member_id: memberId,
        service_code: serviceCode,
        data: null,
        error: 'member_id and service_code are required'
      }
    }
  ];
}

// Find the requested member claim using the nested service schema
const claim = claims.find(
  (record) =>
    record.member_id === memberId &&
    record.service?.service_code === serviceCode
);

// Claim not found
if (!claim) {
  return [
    {
      json: {
        tool: 'CLAIMS',
        status: 'NOT_FOUND',
        member_id: memberId,
        service_code: serviceCode,
        data: null,
        error: 'Claim not found'
      }
    }
  ];
}

// Return only fields useful to servicing
return [
  {
    json: {
      tool: 'CLAIMS',
      status: 'SUCCESS',
      member_id: claim.member_id,
      service_code: claim.service.service_code,
      data: {
        claim_id: claim.claim_id,
        service_name: claim.service.service_name,
        service_date: claim.service_date,
        provider_id: claim.provider_id,
        provider_location_id: claim.provider_location_id,
        status: claim.status,
        denial_reason: claim.denial_reason ?? null,
        authorization_reference:
          claim.authorization_reference ?? null,
        billed_amount: claim.billed_amount,
        allowed_amount: claim.allowed_amount
      },
      error: null
    }
  }
];
